import logging
import requests
import uuid
from functools import wraps
from requests.packages.urllib3.exceptions import InsecureRequestWarning
from taf.nms.nom import nom
from taf.rfrl.utilities.tl_config import get_nom_rest_credentials, get_nom_mgmt_credentials
from datetime import datetime
from taf.rfrl.bts.devices.exceptions import CannotGetTimeFromOperation
requests.packages.urllib3.disable_warnings(InsecureRequestWarning)


def login_to_nom_if_needed(web_fun):
    @wraps(web_fun)
    def wrapper(self, *args, **kwargs):
        self.connect()
        result = web_fun(self, *args, **kwargs)
        return result

    return wrapper


class NomWrapper(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    ROBOT_LISTENER_API_VERSION = 2

    def __init__(self):
        self.ROBOT_LIBRARY_LISTENER = self

        self.nom = nom()
        self._nom_device_name = 'NOM'
        self._client_id = str(self._generate_unique_client_id())
        self._already_connected = False

    def __del__(self):
        self.disconnect()

    def _close(self):
        """
        Called when robot test execution ends
        """
        self.disconnect()

    def connect(self):
        if self._already_connected:
            return

        rest_credentials = get_nom_rest_credentials()
        mgmt_credentials = get_nom_mgmt_credentials()
        nom_rf_secret = self.nom.register_the_client(client_id=self._client_id,
                                                     username=rest_credentials['username'],
                                                     password=rest_credentials['password'],
                                                     apigw_uri=rest_credentials['host'])

        logging.debug("Connection is register with ID: {}".format(self._client_id))

        self.nom.connect_to(user_mgmt_uri=mgmt_credentials['host'],
                            apigw_uri=rest_credentials['host'].split('//')[1],
                            client_id=self._client_id,
                            client_secret=nom_rf_secret,
                            port=rest_credentials['port'],
                            username=rest_credentials['username'],
                            password=rest_credentials['password'],
                            nom_version='nom_v1',
                            secure=True)

        self._already_connected = True

    def disconnect(self):
        if not self._already_connected:
            return
        logging.debug("Delete connection to NOM for ID: {}".format(self._client_id))
        rest_credentials = get_nom_rest_credentials()
        self.nom.delete_the_client(client_id=self._client_id,
                                   username=rest_credentials['username'],
                                   password=rest_credentials['password'],
                                   apigw_uri=rest_credentials['host'])

        self._already_connected = False

    def _get_timestamps_from_opeartion(self, operation_dict, output_dict, name_of_operation):
        """
        Get timestamps from given operation
        :param operation_dict: dict, dictionary with operation timestamps
        :param output_dict: dict, dictionary where timestamps will be stored
        :param name_of_operation: string, name of the operation
        :return: dict with timestamps
        """
        if str(name_of_operation) not in list(output_dict):
            output_dict[str(name_of_operation)] = {}
        if (operation_dict[-1]["status"] == "finished" or operation_dict[-1]["status"] == "failed") and \
                operation_dict[1]["status"] == "ongoing":
            output_dict[str(name_of_operation)]["begin"] = datetime.strptime(str(operation_dict[-2]["timestamp"]),
                                                                             "%Y-%m-%dT%H:%M:%S.%fZ")
            output_dict[str(name_of_operation)]["end"] = datetime.strptime(str(operation_dict[-1]["timestamp"]),
                                                                           "%Y-%m-%dT%H:%M:%S.%fZ")
            return output_dict
        else:
            raise CannotGetTimeFromOperation("Cannot get time fom this operation + {}".format(operation_dict))

    def get_operation_times_from_upload_configuration_operation(self, id_operation):
        """
        Get timestamps from upload configuration operation
        :param id_operation: string, id of upload configuration operation
        :return: dict with timestamps
        """
        output_dict = {}
        help_op = self.nom.get_operation_feedbacks([str(id_operation)])
        help_op = self.nom.get_operation_feedbacks([str(help_op[-1]["message"].split(" ")[-3])])
        provision_operation_details = self.nom.get_operation_status([str(help_op[-1]["message"].split(" ")[-3])])
        output_dict = self._get_timestamps_from_opeartion(provision_operation_details,
                                                          output_dict, "upload_configuration")
        return output_dict

    @login_to_nom_if_needed
    def get_operations_times_from_provision_operation(self, id_operation):
        """
        Get download, validate and activate operation timestamps from provision plan operation
        :param id_operation: string, id of provision operation
        :return: dict with timestamps
        """
        output_dict = {}
        help_op = self.nom.get_operation_feedbacks([str(id_operation)])
        help_op = self.nom.get_operation_feedbacks([str(help_op[-1]["message"].split(" ")[-3])])
        provision_operation_details = self.nom.get_operation_status([str(help_op[-1]["message"].split(" ")[-3])])
        output_dict = self._get_timestamps_from_opeartion(provision_operation_details,
                                                          output_dict, "provision")
        help_op = self.nom.get_operation_feedbacks([str(help_op[-1]["message"].split(" ")[-3])])
        activate_operation_id = str(help_op[-1]["message"].split(" ")[-3])
        activate_operation_details = self.nom.get_operation_status([activate_operation_id])
        output_dict = self._get_timestamps_from_opeartion(activate_operation_details,
                                                          output_dict, "activation")
        help_op = self.nom.get_operation_feedbacks([activate_operation_id])
        validate_operation_id = str(help_op[0]["message"].split(" ")[-3])
        validate_operation_details = self.nom.get_operation_status([validate_operation_id])
        output_dict = self._get_timestamps_from_opeartion(validate_operation_details,
                                                          output_dict, "validation")
        help_op = self.nom.get_operation_feedbacks([validate_operation_id])
        download_operation_id = str(help_op[0]["message"].split(" ")[-3])
        download_operation_details = self.nom.get_operation_status([download_operation_id])
        output_dict = self._get_timestamps_from_opeartion(download_operation_details,
                                                          output_dict, "download")
        return output_dict

    @login_to_nom_if_needed
    def get_operation_times_from_standalone_operation(self, id_operation, name_of_operation="operation"):
        """
        Get operation timestamps from download/validate/activate plan operation
        :param id_operation: string, id of provision operation
        :param name_of_operation: string, name of the operation
        :return: dict with timestamps
        """
        output_dict = {}
        if self.nom.get_operation_status([str(id_operation)])[-1]["status"] == "finished":
            index = -1
        else:
            index = -2
        help_op = self.nom.get_operation_feedbacks([str(id_operation)])
        help_op = self.nom.get_operation_feedbacks([str(help_op[index]["message"].split(" ")[-3])])
        help_op = self.nom.get_operation_feedbacks([str(help_op[index]["message"].split(" ")[-3])])
        operation_id = str(help_op[index]["message"].split(" ")[-3])
        operation_details = self.nom.get_operation_status([operation_id])
        output_dict = self._get_timestamps_from_opeartion(operation_details,
                                                          output_dict, name_of_operation)
        return output_dict

    @staticmethod
    def _generate_unique_client_id():
        return uuid.uuid1()
